"""
    Invert the sign of the given symmetry operation
    Usage:
      new_op = invert_sym(sym_op)
      sym_op = str symmetry operation e.g. 'x,y,z'
      new_op = inverted symmetry
    E.G.
      new_op = invert_sym('x,y,z')
      >> new_op = '-x,-y,-z'
    """
def invert_sym(sym_op: Any) -> object {
    sym_op = sym_op.lower();
    new_op = sym_op.replace('x', '-x').replace('y', '-y').replace('z', '-z').replace(
        '--', '+'
    ).replace(
        '+-', '-'
    );
    return new_op;
}

"""
    Derivative of sigmoid function
    :param x: array-like shape(n_sample, n_feature)
    :return: derivative value (array like)
    """
def dsigmoid(x: Any) -> object {
    return (x * (1.0 - x));
}

"""Sanitize sensitive request headers for logging"""
def sanitize_headers(headers: Any) -> object {
    results = `dict(headers);
    if results.get('Authorization') {
        results['Authorization'] = '***redacted***';
    }
    return results;
}

""" Calculates the difference between the mean of own_team_scores and the mean of the combination of enemy_team_scores, neutral_scores and assassin_scores. """
def non_zero_mean_difference(
    own_team_scores: Any,
    enemy_team_scores: Any,
    neutral_scores: Any,
    assassin_scores: Any,
    weights: Any = (1, 1, 1, 1)
) -> object {
    (own_team_scores, enemy_team_scores, neutral_scores, assassin_scores) = (
        `list(map(lambda (x: Any) { (x * weight); }, scores))
        for (weight, scores) in zip(
            weights,
            [own_team_scores, enemy_team_scores, neutral_scores, assassin_scores]
        )
    );
    good_scores = [
        score
        for score in own_team_scores
        if (score != 0)
    ];
    bad_scores = [
        score
        for score in (enemy_team_scores + neutral_scores + assassin_scores)
        if (score != 0)
    ];
    mean_good_scores = (sum(good_scores) / len(good_scores))
        if (len(good_scores) > 0)
        else 0;
    mean_bad_scores = (sum(bad_scores) / len(bad_scores))
        if (len(bad_scores) > 0)
        else 0;
    mean_difference = mean_good_scores - mean_bad_scores;
    return mean_difference;
}

"""
  Returns the inverse operation of `zip` on `list`.

  Args:
    l (list): the list to unzip
  """
def unzip(l: Any) -> object {
    return `list(map(`list, zip(*l)));
}

"""
    Checks if number is a square

    Taken verbatim from https://stackoverflow.com/questions/2489435/how-could-i-check-if-a-number-is-a-perfect-square
    """
def is_square(apositiveint: Any) -> object {
    x = apositiveint // 2;
    seen = `set([x]);
    while ((x * x) != apositiveint) {
        x = (x + (apositiveint // x)) // 2;
        if (x in seen) {
            return False;
        }
        seen.add(x);
    }
    return True;
}

"""Compute the recall in a zero safe way.

    :param overlap_count: `int` The number of true positives.
    :param gold_count: `int` The number of gold positives (tp + fn)

    :returns: `float` The recall.
    """
def recall(overlap_count: Any, gold_count: Any) -> object {
    if (gold_count == 0) {
        return 0.0;
    }
    return (overlap_count / float(gold_count));
}

"""Reverse the odd_flag list from the encoder"""
def get_odd_flags(odd_flags: Any, blocks: Any, flag_input: Any = False) -> object {
    odd_list = [flag_input];
    for odd_block in odd_flags {
        odd_list += odd_block;
    }
    odd_list.reverse();
    odd_de = blocks.copy();
    i = 0;
    for (m, odd_block) in enumerate(odd_de) {
        odd_de[m] = blocks[m].copy();
        for (n, bottle) in enumerate(odd_block) {
            odd_de[m][n] = odd_list[(i + 1)];
            i += 1;
        }
    }
    return odd_de;
}

