    returns: tuple, (gate_name (str), gate_args (tuple)).
    """
def get_gate_info(gate: Any) -> object {
    g = gate.strip().lower();
    i = g.index("(");
    (gate_name, gate_args) = (g[:i], eval(g[i:]));
    try {
        len(gate_args);
    } except TypeError {
        gate_args = (gate_args, );
    }
    if (gate_name == "cx") {
        gate_name = "cnot";
    }
